1	// Pure helper: pick the kanata window for a hybrid ROI run.
2	//
3	// - start_pc is the PC where vsim resumes execution (from QEMU 1's drain).
4	// - end_pc is taken from explicit_exit_pc when set (pc-mode forwards the
5	//   --hybrid-exit-pc CLI value), otherwise the unique HYBRID_HANDOFF_EXIT
6	//   PC scanned by the CsrTrigger (csr-mode). 0 or >1 exit hits in csr-mode
7	//   raise -- the caller is expected to redirect to pc-mode with explicit
8	//   --pc-end. The returned skip/record produce a single-shot window
9	//   (LoopGate semantics: open on first fetch of start_pc, close on first
10	//   retire of end_pc).
11	
12	#pragma once
13	
14	#include "hybrid/csr_trigger.hpp"
15	#include "hybrid/insn_match.h"
16	
17	#include <cstdint>
18	#include <optional>
19	#include <stdexcept>
20	#include <string>
21	
22	namespace hybrid
23	{
24	
25	struct RoiKanataGate
26	{
27	  uint64_t start_pc;
28	  uint64_t end_pc;
29	  uint64_t skip_iters;
30	  uint64_t record_iters;
31	};
32	
33	inline auto derive_roi_kanata_gate(
34	  const CsrTrigger& trigger, uint64_t resume_pc,
35	  std::optional<uint64_t> explicit_exit_pc) -> RoiKanataGate
36	{
37	  uint64_t end_pc = 0;
38	  if (explicit_exit_pc) {
39	    end_pc = *explicit_exit_pc;
40	  } else {
41	    const auto exits = trigger.pcs_of_kind(HYBRID_HANDOFF_EXIT);
42	    if (exits.empty()) {
43	      throw std::runtime_error(
44	        "--kanata-roi: no csrwi 0x7C0,1 (EXIT) marker found in ELF -- "
45	        "use --mode pc with --pc-end");
46	    }
47	    if (exits.size() > 1) {
48	      throw std::runtime_error(
49	        "--kanata-roi: " + std::to_string(exits.size())
50	        + " csrwi 0x7C0,1 (EXIT) markers in ELF -- "
51	          "use --mode pc with an explicit --pc-end to disambiguate");
52	    }
53	    end_pc = exits.front();
54	  }
55	  return RoiKanataGate{resume_pc, end_pc, /*skip=*/0u, /*record=*/1u};
56	}
57	
58	}  // namespace hybrid
