1	// Pure-logic test for derive_roi_kanata_gate(): given a CsrTrigger and a
2	// resume PC, return the kanata LoopGate that frames the ROI.
3	// - pc-mode: caller passes explicit_exit_pc, that wins.
4	// - csr-mode: the helper picks the unique HYBRID_HANDOFF_EXIT PC from the
5	//   trigger; 0 or >1 raises.
6	
7	#include "hybrid/csr_trigger.hpp"
8	#include "hybrid/kanata_roi.hpp"
9	
10	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
11	#include <doctest.h>
12	
13	#include <cstdint>
14	#include <stdexcept>
15	
16	TEST_CASE("derive_roi_kanata_gate: csr-mode picks the unique EXIT PC")
17	{
18	  hybrid::CsrTrigger trig;
19	  trig.add_pc_hit(0x80000000, HYBRID_HANDOFF_ENTER);
20	  trig.add_pc_hit(0x80000100, HYBRID_HANDOFF_EXIT);
21	
22	  const auto gate =
23	    hybrid::derive_roi_kanata_gate(trig, /*resume_pc=*/0x80000004,
24	                                   /*explicit_exit_pc=*/std::nullopt);
25	  CHECK(gate.start_pc == 0x80000004);
26	  CHECK(gate.end_pc == 0x80000100);
27	  CHECK(gate.skip_iters == 0);
28	  CHECK(gate.record_iters == 1);
29	}
30	
31	TEST_CASE("derive_roi_kanata_gate: pc-mode honors explicit_exit_pc")
32	{
33	  hybrid::CsrTrigger trig;  // empty (PC-mode skips scan in vsim)
34	
35	  const auto gate =
36	    hybrid::derive_roi_kanata_gate(trig, /*resume_pc=*/0x80000010,
37	                                   /*explicit_exit_pc=*/0x80000200);
38	  CHECK(gate.start_pc == 0x80000010);
39	  CHECK(gate.end_pc == 0x80000200);
40	  CHECK(gate.skip_iters == 0);
41	  CHECK(gate.record_iters == 1);
42	}
43	
44	TEST_CASE("derive_roi_kanata_gate: explicit_exit_pc wins over scanned EXITs")
45	{
46	  hybrid::CsrTrigger trig;
47	  trig.add_pc_hit(0x80000100, HYBRID_HANDOFF_EXIT);
48	  trig.add_pc_hit(0x80000200, HYBRID_HANDOFF_EXIT);
49	
50	  const auto gate =
51	    hybrid::derive_roi_kanata_gate(trig, /*resume_pc=*/0x80000004,
52	                                   /*explicit_exit_pc=*/0x80000300);
53	  CHECK(gate.end_pc == 0x80000300);
54	}
55	
56	TEST_CASE("derive_roi_kanata_gate: csr-mode with zero EXIT PCs throws")
57	{
58	  hybrid::CsrTrigger trig;
59	  trig.add_pc_hit(0x80000000, HYBRID_HANDOFF_ENTER);  // no EXIT
60	
61	  CHECK_THROWS_AS(
62	    hybrid::derive_roi_kanata_gate(trig, 0x80000004, std::nullopt),
63	    std::runtime_error);
64	}
65	
66	TEST_CASE("derive_roi_kanata_gate: csr-mode with multiple EXIT PCs throws")
67	{
68	  hybrid::CsrTrigger trig;
69	  trig.add_pc_hit(0x80000100, HYBRID_HANDOFF_EXIT);
70	  trig.add_pc_hit(0x80000200, HYBRID_HANDOFF_EXIT);
71	
72	  CHECK_THROWS_AS(
73	    hybrid::derive_roi_kanata_gate(trig, 0x80000004, std::nullopt),
74	    std::runtime_error);
75	}
