          "--kanata-roi is incompatible with --hybrid-icount "
          "(no single exit PC); use --mode csr or --mode pc instead");
      if (args.resume_from_qemu.empty())
        throw std::runtime_error(
          "--kanata-roi requires --resume-from-qemu");
    }

    if (!args.kanata_file.empty() && !args.kanata_roi)
      sim.enable_kanata(args.kanata_file, args.objdump_file, loop_gate);

